import React, { Suspense, lazy, useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  CircularProgress,
  IconButton,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import { adaptLeadsFormsToTables } from '../../../adapters/workspaceDetailAdapter';
import { workspaceService } from '../../../services/workspaceService';

const TableRecordsPanel = lazy(() => import('./TableRecordsPanel'));

export default function ChildCampaignRecordsDialog({
  open,
  onClose,
  onNoChildCampaign,
  workspaceId,
  accountId,
  parentLeadId,
  parentLeadLabel,
  styles,
}) {
  const [mappings, setMappings] = useState([]);
  const [selectedCampaignId, setSelectedCampaignId] = useState('');
  const [tables, setTables] = useState([]);
  const [selectedTableId, setSelectedTableId] = useState('');
  const [isLoadingMappings, setIsLoadingMappings] = useState(false);
  const [hasLoadedMappings, setHasLoadedMappings] = useState(false);
  const [isLoadingTables, setIsLoadingTables] = useState(false);
  const [error, setError] = useState('');

  const selectedMapping = useMemo(
    () => mappings.find((mapping) => String(mapping.child_campaign_id) === selectedCampaignId),
    [mappings, selectedCampaignId]
  );
  const selectedTable = useMemo(
    () => tables.find((table) => String(table.id) === selectedTableId),
    [selectedTableId, tables]
  );

  const loadMappings = useCallback(async () => {
    if (!open || !workspaceId) return;

    setIsLoadingMappings(true);
    setHasLoadedMappings(false);
    setError('');
    setMappings([]);
    setSelectedCampaignId('');
    setTables([]);
    setSelectedTableId('');

    try {
      const response = await workspaceService.getWorkspaceMappings(workspaceId);
      if (response?.status !== 200) {
        throw new Error(response?.data?.message || 'Unable to load child business services.');
      }

      const childMappings = Array.isArray(response.data?.child_mappings)
        ? response.data.child_mappings
        : [];
      setMappings(childMappings);
      setSelectedCampaignId(String(childMappings[0]?.child_campaign_id ?? ''));
      if (childMappings.length === 0) {
        onNoChildCampaign?.();
      }
    } catch (loadError) {
      setError(
        loadError?.response?.data?.message
        || loadError?.message
        || 'Unable to load child business services.'
      );
    } finally {
      setIsLoadingMappings(false);
      setHasLoadedMappings(true);
    }
  }, [onNoChildCampaign, open, workspaceId]);

  useEffect(() => {
    loadMappings();
  }, [loadMappings]);

  useEffect(() => {
    let isCurrent = true;

    async function loadTables() {
      if (!selectedMapping?.child_campaign_id) {
        setTables([]);
        setSelectedTableId('');
        return;
      }

      setIsLoadingTables(true);
      setError('');

      try {
        const response = await workspaceService.getWorkspaceTables(
          selectedMapping.child_campaign_id
        );
        if (response?.status !== 200 && response?.status !== 201) {
          throw new Error(response?.data?.message || 'Unable to load child campaign forms.');
        }

        const nextTables = adaptLeadsFormsToTables(response.data).map((table) => ({
          ...table,
          campaignName: selectedMapping.child_campaign_name,
        }));
        if (isCurrent) {
          setTables(nextTables);
          setSelectedTableId(String(nextTables[0]?.id ?? ''));
        }
      } catch (loadError) {
        if (isCurrent) {
          setTables([]);
          setSelectedTableId('');
          setError(
            loadError?.response?.data?.message
            || loadError?.message
            || 'Unable to load child campaign forms.'
          );
        }
      } finally {
        if (isCurrent) setIsLoadingTables(false);
      }
    }

    loadTables();
    return () => {
      isCurrent = false;
    };
  }, [selectedMapping]);

  const handleCampaignChange = (_event, campaignId) => {
    setSelectedCampaignId(String(campaignId));
  };

  const handleTableChange = (_event, tableId) => {
    setSelectedTableId(String(tableId));
  };

  const title = selectedMapping?.child_campaign_name
    ? `Child leads · ${selectedMapping.child_campaign_name}`
    : 'Child campaign leads';

  if (!open || !hasLoadedMappings || isLoadingMappings) return null;

  return (
    <Box
      component="section"
      aria-label={title}
      sx={{
        mt: 3,
        p: { xs: 1.5, sm: 2.5 },
        border: '1px solid',
        borderColor: 'divider',
        borderRadius: 2,
        bgcolor: 'background.paper',
      }}
    >
      <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 2 }}>
        <Box sx={{ minWidth: 0 }}>
          <Typography component="h2" variant="h6">
            {title}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
            Showing child campaign records linked to lead {parentLeadLabel || parentLeadId}.
          </Typography>
        </Box>
        <IconButton aria-label="Close child campaign records" onClick={onClose} size="small">
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>

      {isLoadingMappings ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 5 }}>
          <CircularProgress size={28} />
        </Box>
      ) : null}

      {!isLoadingMappings && !error && mappings.length === 0 ? (
        <Typography color="text.secondary" sx={{ py: 3 }}>
          No child campaigns are mapped to this business service.
        </Typography>
      ) : null}

      {!isLoadingMappings && mappings.length > 0 ? (
        <Tabs
          value={selectedCampaignId}
          onChange={handleCampaignChange}
          variant="scrollable"
          scrollButtons="auto"
          aria-label="Child campaigns"
          sx={{ borderBottom: 1, borderColor: 'divider' }}
        >
          {mappings.map((mapping) => (
            <Tab
              key={mapping.child_campaign_id}
              value={String(mapping.child_campaign_id)}
              label={mapping.child_campaign_name || mapping.child_campaign_id}
            />
          ))}
        </Tabs>
      ) : null}

      {error ? <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert> : null}

      {isLoadingTables ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 5 }}>
          <CircularProgress size={28} />
        </Box>
      ) : null}

      {!isLoadingTables && !error && selectedMapping && tables.length === 0 ? (
        <Typography color="text.secondary" sx={{ py: 3 }}>
          This child campaign has no lead forms.
        </Typography>
      ) : null}

      {!isLoadingTables && !error && tables.length > 0 ? (
        <>
          {tables.length > 1 ? (
            <Tabs
              value={selectedTableId}
              onChange={handleTableChange}
              variant="scrollable"
              scrollButtons="auto"
              aria-label="Child campaign lead forms"
              sx={{ mt: 1, borderBottom: 1, borderColor: 'divider' }}
            >
              {tables.map((table) => (
                <Tab key={table.id} value={String(table.id)} label={table.name} />
              ))}
            </Tabs>
          ) : null}

          {selectedTable ? (
            <Box sx={{ pt: 1 }}>
              <Suspense
                fallback={
                  <Box sx={{ display: 'flex', justifyContent: 'center', py: 5 }}>
                    <CircularProgress size={28} />
                  </Box>
                }
              >
                <TableRecordsPanel
                  workspaceId={selectedMapping.child_campaign_id}
                  accountId={accountId}
                  table={selectedTable}
                  styles={styles}
                  showHeader={false}
                  parentLeadId={parentLeadId}
                />
              </Suspense>
            </Box>
          ) : null}
        </>
      ) : null}
    </Box>
  );
}
